510	      rIdx = (n + pages.length) % pages.length
511	      pages.forEach((el, i) => el.classList.toggle("active", i === rIdx))
512	      loadPage(pages[rIdx])
513	      document.querySelectorAll("#revDots .dot").forEach((d, i) => d.classList.toggle("on", i === rIdx))
514	    }
515	    w.revNext = (d: number) => showR(rIdx + d)
516	
517	    // swipe for review modal
518	    const revStage = document.getElementById("revStage")
519	    if (revStage) {
520	      let rtx = 0
521	      revStage.addEventListener("touchstart", (e) => { rtx = (e as TouchEvent).touches[0].clientX }, { passive: true })
522	      revStage.addEventListener("touchend", (e) => {
523	        const dx = (e as TouchEvent).changedTouches[0].clientX - rtx
524	        if (Math.abs(dx) > 40) showR(rIdx + (dx < 0 ? 1 : -1))
525	      }, { passive: true })
526	    }
527	
528	    w.openM = (id: string) => {
529	      const m = document.getElementById(id)
530	      if (!m) return
531	      m.classList.add("open")
532	      document.body.style.overflow = "hidden"
533	      if (id === "sysModal") {
534	        showS(0)
535	        const mbody = m.querySelector(".mbody") as HTMLElement | null
536	        const hint = document.getElementById("sysScrollHint")
537	        if (mbody && hint) {
538	          hint.classList.remove("hidden")
539	          const onScroll = () => {
540	            const atBottom = mbody.scrollHeight - mbody.scrollTop - mbody.clientHeight < 40
541	            hint.classList.toggle("hidden", atBottom)
542	          }
543	          mbody.addEventListener("scroll", onScroll, { passive: true })
544	        }
545	      }
546	      if (id === "reviewModal") {
547	        const pages = rPages()
548	        const revDots = document.getElementById("revDots")
549	        if (revDots && !revDots.childElementCount) {
550	          pages.forEach((_, i) => {
551	            const b = document.createElement("span")
552	            b.className = "dot" + (i === 0 ? " on" : "")
553	            b.onclick = () => showR(i)
554	            revDots.appendChild(b)
555	          })
556	        }
557	        showR(0)
558	      }
559	    }
560	    w.closeM = (id: string) => {
561	      const m = document.getElementById(id)
562	      if (!m) return
563	      m.classList.remove("open")
564	      document.body.style.overflow = ""
565	    }
566	    w.sysNext = (d: number) => showS(sIdx + d)
567	
568	    // build system dots
569	    const sysDots = document.getElementById("sysDots")
570	    if (sysDots && !sysDots.childElementCount) {
571	      slides().forEach((_, i) => {
572	        const b = document.createElement("span")
573	        b.className = "dot" + (i === 0 ? " on" : "")
574	        b.onclick = () => showS(i)
575	        sysDots.appendChild(b)
576	      })
577	    }
578	
579	    // backdrop click to close
580	    const modalHandlers: Array<[Element, (e: Event) => void]> = []
581	    document.querySelectorAll(".modal").forEach((m) => {
582	      const h = (e: Event) => {
583	        if (e.target === m) w.closeM((m as HTMLElement).id)
584	      }
585	      m.addEventListener("click", h)
586	      modalHandlers.push([m, h])
587	    })
588	
589	    // keyboard
590	    const onKey = (e: KeyboardEvent) => {
591	      if (e.key === "Escape") {
592	        w.closeM("sysModal")
593	        w.closeM("curModal")
594	        w.closeM("reviewModal")
595	      }
596	      const rm = document.getElementById("reviewModal")
597	      if (rm && rm.classList.contains("open")) {
598	        if (e.key === "ArrowRight") w.revNext(1)
599	        if (e.key === "ArrowLeft") w.revNext(-1)
600	      }
601	      const sm = document.getElementById("sysModal")
602	      if (sm && sm.classList.contains("open")) {
603	        if (e.key === "ArrowRight") w.sysNext(1)
604	        if (e.key === "ArrowLeft") w.sysNext(-1)
605	      }
606	    }
607	    document.addEventListener("keydown", onKey)
608	
609	    // hamburger nav
610	    w.toggleNav = () => {
611	      document.getElementById("hamburger")?.classList.toggle("open")
612	      document.getElementById("mobnav")?.classList.toggle("open")
613	    }
614	    w.closeNav = () => {
615	      document.getElementById("hamburger")?.classList.remove("open")
616	      document.getElementById("mobnav")?.classList.remove("open")
617	    }
618	
619	    // generic review sliders (영상 후기 / 사진 리뷰)
620	    document.querySelectorAll(".slider").forEach((sl) => {
621	      const items = Array.from(sl.querySelectorAll(".track > .sl")) as HTMLElement[]
622	      const dotsC = sl.querySelector(".sdots")
623	      const track = sl.querySelector(".track") as HTMLElement | null
624	      const isSlide = sl.classList.contains("photo")
625	      let idx = 0
626	      const show = (n: number) => {
627	        if (!items.length) return
628	        idx = (n + items.length) % items.length
629	        if (isSlide && track) {
630	          track.style.transform = `translateX(-${idx * 100}%)`
631	        } else {
632	          items.forEach((el, i) => el.classList.toggle("active", i === idx))
633	        }
634	        if (dotsC) dotsC.querySelectorAll(".dot").forEach((d, i) => d.classList.toggle("on", i === idx))
635	      }
636	      const pv = sl.querySelector(".sarrow.prev") as HTMLElement | null
637	      const nx = sl.querySelector(".sarrow.next") as HTMLElement | null
638	      if (pv) pv.onclick = () => show(idx - 1)
639	      if (nx) nx.onclick = () => show(idx + 1)
640	      let tx = 0
641	      sl.addEventListener("touchstart", (e) => { tx = (e as TouchEvent).touches[0].clientX }, { passive: true })
642	      sl.addEventListener("touchend", (e) => {
643	        const dx = (e as TouchEvent).changedTouches[0].clientX - tx
644	        if (Math.abs(dx) > 40) show(dx < 0 ? idx + 1 : idx - 1)
645	      }, { passive: true })
646	      if (dotsC && !dotsC.childElementCount) {
647	        items.forEach((_, i) => {
648	          const b = document.createElement("span")
649	          b.className = "dot" + (i === 0 ? " on" : "")
650	          b.onclick = () => show(i)
651	          dotsC.appendChild(b)
652	        })
653	      }
654	      show(0)
655	    })
656	
657	    return () => {
658	      document.removeEventListener("keydown", onKey)
659	      modalHandlers.forEach(([m, h]) => m.removeEventListener("click", h))
660	    }
661	  }, [])
662	
663	  return (
664	    <>
665	      <style dangerouslySetInnerHTML={{ __html: CSS }} />
666	      <div dangerouslySetInnerHTML={{ __html: BODY }} />
667	    </>
668	  )
669	}
