            <img data-src="https://www.systemize.kr/images/2.jpg" alt="후기 4" />
            <img data-src="https://www.systemize.kr/images/4.png" alt="후기 5" />
            <img data-src="https://www.systemize.kr/images/05.png" alt="후기 6" />
          </div>
          <div class="rev3pg">
            <img data-src="https://www.systemize.kr/images/6.png" alt="후기 7" />
            <img data-src="https://www.systemize.kr/images/7.png" alt="후기 8" />
            <img data-src="https://www.systemize.kr/images/8.png" alt="후기 9" />
          </div>
          <div class="rev3pg">
            <img data-src="https://www.systemize.kr/images/9.jpg" alt="후기 10" />
          </div>
        </div>
        <div class="revnav">
          <button class="arrow prev" onclick="revNext(-1)">‹</button>
          <div class="dots" id="revDots"></div>
          <button class="arrow next" onclick="revNext(1)">›</button>
        </div>
      </div>
