  </div>

  <div class="modal" id="curModal">
    <div class="mbox">
      <div class="mhead"><div class="mt">압도적 커리큘럼 · 진짜 국어의 시작</div><div class="mclose" onclick="closeM('curModal')">✕</div></div>
      <div class="mbody">
        <div class="curcap">커리큘럼 영상</div>
        <div class="curvid"><iframe src="https://www.youtube.com/embed/kGNdiMcnrn8?si=9hWI5e9_rc-Ss-oj" title="커리큘럼 영상" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
        <div class="curcap">체계 국어 커리큘럼</div>
        <img class="curimg" src="https://www.systemize.kr/images/curriculum-2025-light.png" alt="체계 국어 커리큘럼" loading="lazy" />
      </div>
    </div>
  </div>
`

export default function LandingPage() {
  useEffect(() => {
    const w = window as any
    let sIdx = 0
    const slides = () => Array.from(document.querySelectorAll("#sysModal .slide")) as HTMLElement[]
    const showS = (n: number) => {
      const s = slides()
      const total = s.length
      if (!total) return
      sIdx = (n + total) % total
      s.forEach((el, i) => el.classList.toggle("active", i === sIdx))
      const cap = document.getElementById("sysCap")
      if (cap) cap.textContent = s[sIdx].dataset.cap || ""
      document.querySelectorAll("#sysDots .dot").forEach((d, i) => d.classList.toggle("on", i === sIdx))
    }
    // review modal
    let rIdx = 0
    const rPages = () => Array.from(document.querySelectorAll("#revStage .rev3pg")) as HTMLElement[]
    const loadPage = (el: HTMLElement) => {
      el.querySelectorAll<HTMLImageElement>("img[data-src]").forEach((img) => {
        img.src = img.dataset.src!
        img.removeAttribute("data-src")
      })
    }
    const showR = (n: number) => {
      const pages = rPages()
      if (!pages.length) return
      rIdx = (n + pages.length) % pages.length
      pages.forEach((el, i) => el.classList.toggle("active", i === rIdx))
      loadPage(pages[rIdx])
      document.querySelectorAll("#revDots .dot").forEach((d, i) => d.classList.toggle("on", i === rIdx))
    }
    w.revNext = (d: number) => showR(rIdx + d)

    // swipe for review modal
    const revStage = document.getElementById("revStage")
    if (revStage) {
      let rtx = 0
      revStage.addEventListener("touchstart", (e) => { rtx = (e as TouchEvent).touches[0].clientX }, { passive: true })
      revStage.addEventListener("touchend", (e) => {
        const dx = (e as TouchEvent).changedTouches[0].clientX - rtx
        if (Math.abs(dx) > 40) showR(rIdx + (dx < 0 ? 1 : -1))
      }, { passive: true })
    }

    w.openM = (id: string) => {
      const m = document.getElementById(id)
      if (!m) return
      m.classList.add("open")
      document.body.style.overflow = "hidden"
      if (id === "sysModal") {
        showS(0)
        const mbody = m.querySelector(".mbody") as HTMLElement | null
        const hint = document.getElementById("sysScrollHint")
        if (mbody && hint) {
          hint.classList.remove("hidden")
          const onScroll = () => {
            const atBottom = mbody.scrollHeight - mbody.scrollTop - mbody.clientHeight < 40
            hint.classList.toggle("hidden", atBottom)
          }
          mbody.addEventListener("scroll", onScroll, { passive: true })
        }
      }
      if (id === "reviewModal") {
        const pages = rPages()
        const revDots = document.getElementById("revDots")
        if (revDots && !revDots.childElementCount) {
          pages.forEach((_, i) => {
            const b = document.createElement("span")
            b.className = "dot" + (i === 0 ? " on" : "")
            b.onclick = () => showR(i)
            revDots.appendChild(b)
          })
        }
        showR(0)
      }
    }
    w.closeM = (id: string) => {
      const m = document.getElementById(id)
      if (!m) return
      m.classList.remove("open")
      document.body.style.overflow = ""
    }
    w.sysNext = (d: number) => showS(sIdx + d)

    // build system dots
    const sysDots = document.getElementById("sysDots")
    if (sysDots && !sysDots.childElementCount) {
      slides().forEach((_, i) => {
        const b = document.createElement("span")
        b.className = "dot" + (i === 0 ? " on" : "")
        b.onclick = () => showS(i)
        sysDots.appendChild(b)
      })
    }

    // backdrop click to close
    const modalHandlers: Array<[Element, (e: Event) => void]> = []
    document.querySelectorAll(".modal").forEach((m) => {
      const h = (e: Event) => {
        if (e.target === m) w.closeM((m as HTMLElement).id)
      }
      m.addEventListener("click", h)
      modalHandlers.push([m, h])
    })

    // keyboard
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        w.closeM("sysModal")
        w.closeM("curModal")
        w.closeM("reviewModal")
      }
      const rm = document.getElementById("reviewModal")
      if (rm && rm.classList.contains("open")) {
        if (e.key === "ArrowRight") w.revNext(1)
        if (e.key === "ArrowLeft") w.revNext(-1)
      }
      const sm = document.getElementById("sysModal")
      if (sm && sm.classList.contains("open")) {
        if (e.key === "ArrowRight") w.sysNext(1)
        if (e.key === "ArrowLeft") w.sysNext(-1)
      }
    }
    document.addEventListener("keydown", onKey)

    // hamburger nav
    w.toggleNav = () => {
      document.getElementById("hamburger")?.classList.toggle("open")
      document.getElementById("mobnav")?.classList.toggle("open")
    }
    w.closeNav = () => {
      document.getElementById("hamburger")?.classList.remove("open")
      document.getElementById("mobnav")?.classList.remove("open")
    }

    // generic review sliders (영상 후기 / 사진 리뷰)
    document.querySelectorAll(".slider").forEach((sl) => {
      const items = Array.from(sl.querySelectorAll(".track > .sl")) as HTMLElement[]
      const dotsC = sl.querySelector(".sdots")
      const track = sl.querySelector(".track") as HTMLElement | null
      const isSlide = sl.classList.contains("photo")
      let idx = 0
      const show = (n: number) => {
        if (!items.length) return
        idx = (n + items.length) % items.length
        if (isSlide && track) {
          track.style.transform = `translateX(-${idx * 100}%)`
        } else {
          items.forEach((el, i) => el.classList.toggle("active", i === idx))
        }
        if (dotsC) dotsC.querySelectorAll(".dot").forEach((d, i) => d.classList.toggle("on", i === idx))
      }
      const pv = sl.querySelector(".sarrow.prev") as HTMLElement | null
      const nx = sl.querySelector(".sarrow.next") as HTMLElement | null
      if (pv) pv.onclick = () => show(idx - 1)
      if (nx) nx.onclick = () => show(idx + 1)
      let tx = 0
      sl.addEventListener("touchstart", (e) => { tx = (e as TouchEvent).touches[0].clientX }, { passive: true })
      sl.addEventListener("touchend", (e) => {
        const dx = (e as TouchEvent).changedTouches[0].clientX - tx
        if (Math.abs(dx) > 40) show(dx < 0 ? idx + 1 : idx - 1)
      }, { passive: true })
      if (dotsC && !dotsC.childElementCount) {
        items.forEach((_, i) => {
          const b = document.createElement("span")
          b.className = "dot" + (i === 0 ? " on" : "")
          b.onclick = () => show(i)
          dotsC.appendChild(b)
        })
      }
      show(0)
    })

    return () => {
      document.removeEventListener("keydown", onKey)
      modalHandlers.forEach(([m, h]) => m.removeEventListener("click", h))
    }
  }, [])

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div dangerouslySetInnerHTML={{ __html: BODY }} />
    </>
  )
}

