CREATE POLICY "homework_update_own" ON public.homework FOR UPDATE USING (auth.uid() = user_id);

-- Missions RLS policies (public read)
CREATE POLICY "missions_select_all" ON public.missions FOR SELECT USING (TRUE);

-- User missions RLS policies
CREATE POLICY "user_missions_select_own" ON public.user_missions FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "user_missions_insert_own" ON public.user_missions FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "user_missions_update_own" ON public.user_missions FOR UPDATE USING (auth.uid() = user_id);

-- Shop items RLS policies (public read)
CREATE POLICY "shop_items_select_all" ON public.shop_items FOR SELECT USING (TRUE);

-- User shop items RLS policies
CREATE POLICY "user_shop_items_select_own" ON public.user_shop_items FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "user_shop_items_insert_own" ON public.user_shop_items FOR INSERT WITH CHECK (auth.uid() = user_id);

-- QA posts RLS policies
CREATE POLICY "qa_posts_select_all" ON public.qa_posts FOR SELECT USING (TRUE);
CREATE POLICY "qa_posts_insert_own" ON public.qa_posts FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "qa_posts_update_own" ON public.qa_posts FOR UPDATE USING (auth.uid() = user_id);

-- QA comments RLS policies
CREATE POLICY "qa_comments_select_all" ON public.qa_comments FOR SELECT USING (TRUE);
CREATE POLICY "qa_comments_insert_own" ON public.qa_comments FOR INSERT WITH CHECK (auth.uid() = user_id);

-- Reviews RLS policies
