-- Add role and classroom access columns to profiles table
ALTER TABLE profiles
ADD COLUMN IF NOT EXISTS role text DEFAULT 'user' CHECK (role IN ('admin', 'user')),
ADD COLUMN IF NOT EXISTS has_classroom_access boolean DEFAULT false;

-- Set okskt1996@naver.com as admin with full access
UPDATE profiles
SET role = 'admin', has_classroom_access = true
WHERE id IN (
  SELECT id FROM auth.users WHERE email = 'okskt1996@naver.com'
);

-- Create policy for admin to view all profiles
CREATE POLICY IF NOT EXISTS "profiles_select_all_for_admin"
ON profiles
FOR SELECT
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.id = auth.uid() AND profiles.role = 'admin'
  )
);

-- Create policy for admin to update all profiles
CREATE POLICY IF NOT EXISTS "profiles_update_all_for_admin"
ON profiles
FOR UPDATE
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.id = auth.uid() AND profiles.role = 'admin'
  )
);

-- Add index for faster role lookups
CREATE INDEX IF NOT EXISTS idx_profiles_role ON profiles(role);
CREATE INDEX IF NOT EXISTS idx_profiles_has_classroom_access ON profiles(has_classroom_access);
