675	  (function(){var dots=document.getElementById('sysDots');if(dots&&!dots.childElementCount){slides().forEach(function(_,i){var b=document.createElement('span');b.className='dot'+(i===0?' on':'');b.onclick=function(){showS(i);};dots.appendChild(b);});}})();
676	  document.querySelectorAll('.modal').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)closeM(m.id);});});
677	  document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeM('sysModal');closeM('curModal');}if(document.getElementById('sysModal').classList.contains('open')){if(e.key==='ArrowRight')sysNext(1);if(e.key==='ArrowLeft')sysNext(-1);}});
678	  document.querySelectorAll('.slider').forEach(function(sl){
679	    var items=sl.querySelectorAll('.track > .sl');var dotsC=sl.querySelector('.sdots');var idx=0;
680	    function show(n){idx=(n+items.length)%items.length;items.forEach(function(el,i){el.classList.toggle('active',i===idx);});if(dotsC)dotsC.querySelectorAll('.dot').forEach(function(d,i){d.classList.toggle('on',i===idx);});}
681	    var pv=sl.querySelector('.sarrow.prev'),nx=sl.querySelector('.sarrow.next');
682	    if(pv)pv.onclick=function(){show(idx-1);};if(nx)nx.onclick=function(){show(idx+1);};
683	    if(dotsC&&!dotsC.childElementCount){items.forEach(function(_,i){var b=document.createElement('span');b.className='dot'+(i===0?' on':'');b.onclick=function(){show(i);};dotsC.appendChild(b);});}
684	    show(0);
685	  });
686	</script>
687	
688	</body>
689	</html>
