input.content:
"use client"

import { useEffect } from "react"

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;500;600;700;900&family=Noto+Sans+KR:wght@300;400;500;700&display=swap');
:root{
  --bg:#0b0a09; --bg2:#100f0d; --ink:#f3efe6; --muted:#8d877b; --muted2:#5d584f;
  --gold:#c9a24b; --goldsoft:rgba(201,162,75,.32); --line:rgba(201,162,75,.16);
  --serif:"Noto Serif KR",Georgia,serif; --sans:"Noto Sans KR","Pretendard",sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;}
body{background:
    radial-gradient(ellipse 80% 50% at 50% -10%,rgba(201,162,75,.06),transparent 60%),
    radial-gradient(ellipse 60% 40% at 100% 100%,rgba(201,162,75,.04),transparent 55%),
    var(--bg);
  color:var(--ink);font-family:var(--sans);font-weight:300;-webkit-font-smoothing:antialiased;line-height:1.7;letter-spacing:.2px;}
.wrap{max-width:1180px;margin:0 auto;padding:0 40px;}
.ser{font-family:var(--serif);}
.gold{color:var(--gold);}
.kicker{font-size:11px;letter-spacing:5px;color:var(--gold);text-transform:uppercase;}
.rule{width:46px;height:1px;background:var(--gold);margin:26px auto;}
a{color:inherit;text-decoration:none;}

.nav{position:fixed;top:0;left:0;right:0;z-index:60;background:linear-gradient(180deg,rgba(11,10,9,.92),transparent);}
.nav .inner{display:flex;align-items:center;justify-content:space-between;height:80px;max-width:1180px;margin:0 auto;padding:0 40px;}
.brand{font-family:var(--serif);font-weight:700;font-size:20px;letter-spacing:4px;}
.nav nav{display:flex;gap:28px;font-size:12px;letter-spacing:2px;color:var(--muted);}
.nav nav a:hover{color:var(--ink);}
@media(max-width:980px){.nav nav{display:none;}}

.hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
  background:radial-gradient(ellipse at 50% 18%,rgba(201,162,75,.08),transparent 55%);padding:120px 24px;position:relative;}
.eyebrow{font-size:11px;font-weight:500;letter-spacing:5px;color:var(--gold);text-transform:uppercase;margin-bottom:34px;}
.hero h1{font-family:var(--serif);font-weight:500;font-size:92px;line-height:1.04;letter-spacing:-2px;}
.hero h1 b{font-weight:900;}
.hero .lede{color:var(--gold);font-size:18px;letter-spacing:2px;margin-top:34px;font-weight:400;}
.hero .lede2{color:var(--muted);font-size:16px;margin-top:14px;font-weight:300;max-width:560px;}
@media(max-width:760px){.hero h1{font-size:50px;}}

.btn{display:inline-block;font-size:13px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);border:1px solid var(--gold);padding:18px 40px;border-radius:2px;transition:.2s;background:transparent;cursor:pointer;}
.btn:hover{background:var(--gold);color:#0b0a09;}
.btn.fill{background:var(--gold);color:#0b0a09;}
.btn.fill:hover{background:#dcb45f;}
.btnrow{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:46px;}
@media(max-width:760px){.btn{padding:15px 26px;font-size:12px;letter-spacing:2px;}}

section{padding:150px 0;}
.center{text-align:center;}
.display{font-family:var(--serif);font-weight:500;font-size:48px;line-height:1.28;letter-spacing:-1px;margin-top:24px;}
.display b{font-weight:900;}
.sub{color:var(--muted);font-size:16px;font-weight:300;margin-top:26px;max-width:660px;margin-left:auto;margin-right:auto;}
@media(max-width:760px){.display{font-size:32px;}section{padding:96px 0;}}

.manifesto{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--bg2);}
.manifesto .display{font-size:44px;}

.coll{display:grid;grid-template-columns:repeat(3,1fr);margin-top:80px;border-top:1px solid var(--line);}
@media(max-width:820px){.coll{grid-template-columns:1fr;}}
.col{padding:54px 38px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);position:relative;}
.col:last-child{border-right:none;}
.col .no{font-family:var(--serif);font-size:14px;letter-spacing:3px;color:var(--gold);}
.col h3{font-family:var(--serif);font-weight:600;font-size:25px;margin:22px 0 14px;letter-spacing:-.5px;}
.col p{color:var(--muted);font-size:14px;font-weight:300;}
.detail{position:absolute;top:20px;right:20px;font-size:10px;letter-spacing:2px;color:var(--gold);border:1px solid var(--goldsoft);padding:6px 12px;border-radius:2px;cursor:pointer;text-transform:uppercase;transition:.2s;}
.detail:hover{background:var(--gold);color:#0b0a09;}

.ed{display:grid;grid-template-columns:1fr 1fr;align-items:stretch;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
@media(max-width:820px){.ed{grid-template-columns:1fr;}}
.ed .img{min-height:560px;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;border-right:1px solid var(--line);position:relative;overflow:hidden;}
.ed .img::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 70% 20%,rgba(201,162,75,.10),transparent 60%);pointer-events:none;}
.ed .txt{padding:80px 64px;display:flex;flex-direction:column;justify-content:center;}
@media(max-width:820px){.ed .txt{padding:56px 32px;}.ed .img{min-height:420px;border-right:none;border-bottom:1px solid var(--line);}}
.ed h2{font-family:var(--serif);font-weight:500;font-size:36px;line-height:1.3;letter-spacing:-1px;margin:20px 0 30px;}
.ed ul{list-style:none;display:flex;flex-direction:column;gap:16px;}
.ed li{font-size:16px;color:var(--ink);padding-left:26px;position:relative;font-weight:300;}
.ed li::before{content:"";position:absolute;left:0;top:11px;width:14px;height:1px;background:var(--gold);}
.ed .note{color:var(--muted2);font-size:13px;margin-top:34px;letter-spacing:.5px;}

.two{display:grid;grid-template-columns:1fr 1fr;margin-top:70px;border:1px solid var(--line);text-align:left;}
@media(max-width:760px){.two{grid-template-columns:1fr;}}
.two .cell{padding:50px 44px;}
.two .cell.fit{border-right:1px solid var(--line);}
@media(max-width:760px){.two .cell.fit{border-right:none;border-bottom:1px solid var(--line);}}
.two h4{font-family:var(--serif);font-size:21px;margin-bottom:26px;}
.two .fit h4{color:var(--gold);}
.two .noo h4{color:var(--muted);}
.two ul{list-style:none;display:flex;flex-direction:column;gap:15px;}
.two li{font-size:15px;padding-left:26px;position:relative;font-weight:300;}
.two .fit li{color:var(--ink);}
.two .fit li::before{content:"\\2713";position:absolute;left:0;color:var(--gold);}
.two .noo li{color:var(--muted);}
.two .noo li::before{content:"\\2715";position:absolute;left:0;color:var(--muted2);}

.sys{background:var(--bg2);}
.syslist{max-width:760px;margin:70px auto 0;}
.sysrow{display:flex;align-items:baseline;gap:30px;padding:26px 0;border-top:1px solid var(--line);}
.sysrow .k{font-family:var(--serif);font-size:13px;letter-spacing:3px;color:var(--gold);width:140px;flex-shrink:0;}
.sysrow .t{font-size:19px;font-weight:300;}
@media(max-width:620px){.sysrow{flex-direction:column;gap:6px;}.sysrow .k{width:auto;}}
.sysdetail{max-width:760px;margin:30px auto 0;text-align:right;}
.detailline{display:inline-block;font-size:11px;letter-spacing:2px;color:var(--gold);border:1px solid var(--goldsoft);padding:10px 18px;border-radius:2px;cursor:pointer;text-transform:uppercase;transition:.2s;}
.detailline:hover{background:var(--gold);color:#0b0a09;}

.flow{display:grid;grid-template-columns:repeat(4,1fr);margin-top:70px;border-top:1px solid var(--line);border-left:1px solid var(--line);text-align:left;}
@media(max-width:860px){.flow{grid-template-columns:repeat(2,1fr);}}
@media(max-width:520px){.flow{grid-template-columns:1fr;}}
.fstep{padding:34px 26px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);}
.fstep .n{font-family:var(--serif);color:var(--gold);font-size:13px;letter-spacing:2px;}
.fstep .ti{font-size:17px;margin-top:12px;}
.fstep .ds{color:var(--muted);font-size:13px;margin-top:8px;}

.checklist{max-width:780px;margin:50px auto 0;display:grid;grid-template-columns:1fr 1fr;gap:16px 44px;text-align:left;}
@media(max-width:680px){.checklist{grid-template-columns:1fr;}}
.ci{font-size:16px;padding-left:28px;position:relative;color:var(--ink);font-weight:300;}
.ci::before{content:"\\2713";position:absolute;left:0;color:var(--gold);}

.report{max-width:560px;margin:54px auto 0;border:1px solid var(--line);border-radius:10px;background:var(--bg);text-align:left;overflow:hidden;}
.report .rh{background:var(--bg2);padding:18px 26px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;}
.report .rh b{font-family:var(--serif);color:var(--gold);font-size:16px;}
.report .rh span{color:var(--muted2);font-size:12px;letter-spacing:1px;}
.report .rb{padding:8px 26px 22px;}
.report .row{display:flex;justify-content:space-between;gap:16px;font-size:15px;border-bottom:1px dashed var(--line);padding:14px 0;}
.report .row:last-child{border-bottom:none;}
.report .row span:first-child{color:var(--muted);}
.report .row b{color:var(--gold);font-weight:500;}

.chat{max-width:640px;margin:50px auto 0;display:flex;flex-direction:column;gap:14px;text-align:left;}
.bub{max-width:82%;padding:16px 20px;border-radius:14px;font-size:15px;line-height:1.6;}
.bub .who{font-size:11px;letter-spacing:1px;opacity:.7;margin-bottom:6px;display:block;}
.bub.q{align-self:flex-start;background:#1c1b17;color:var(--ink);border:1px solid var(--line);border-bottom-left-radius:4px;}
.bub.a{align-self:flex-end;background:var(--gold);color:#0b0a09;font-weight:400;border-bottom-right-radius:4px;}

.cases{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-top:54px;background:var(--line);border:1px solid var(--line);}
@media(max-width:760px){.cases{grid-template-columns:1fr;}}
.case{background:var(--bg);padding:36px 24px;text-align:center;}
.case .big{font-family:var(--serif);font-size:30px;color:var(--gold);font-weight:600;letter-spacing:-1px;}
.case .cl{color:var(--muted);font-size:13px;margin-top:12px;line-height:1.6;}

.process{max-width:720px;margin:60px auto 0;text-align:left;}
.prow{display:flex;gap:24px;padding:22px 0;border-top:1px solid var(--line);align-items:baseline;}
.prow .pn{font-family:var(--serif);color:var(--gold);font-size:18px;width:42px;flex-shrink:0;}
.prow .pt{font-size:17px;}
.prow .pt small{color:var(--muted);display:block;font-size:13px;margin-top:5px;font-weight:300;}

.imgslot{border:1px dashed rgba(201,162,75,.45);border-radius:10px;background:linear-gradient(160deg,#15140f,#0d0c0a);min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center;padding:48px 28px;}
.imgslot .pi{font-size:30px;color:var(--goldsoft);}
.imgslot .ph{font-size:11px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;}
.imgslot .pd{font-size:15px;color:var(--ink);max-width:440px;}
.imgslot small{color:var(--muted2);font-size:12px;letter-spacing:.5px;}
.imgslot.short{min-height:220px;}
.slotgrid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:50px;}
@media(max-width:760px){.slotgrid{grid-template-columns:1fr;}}

.nums{display:grid;grid-template-columns:repeat(4,1fr);margin-top:74px;border-top:1px solid var(--line);border-left:1px solid var(--line);}
@media(max-width:760px){.nums{grid-template-columns:repeat(2,1fr);}}
.num{padding:48px 16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);text-align:center;}
.num .v{font-family:var(--serif);font-size:42px;font-weight:600;color:var(--gold);letter-spacing:-1px;}
.num .l{color:var(--muted);font-size:12px;letter-spacing:1px;margin-top:12px;line-height:1.6;}

.revwrap{display:grid;grid-template-columns:1fr 1fr;gap:46px;margin-top:64px;text-align:left;align-items:start;}
@media(max-width:880px){.revwrap{grid-template-columns:1fr;gap:60px;}}
.revhead{font-family:var(--serif);font-size:22px;font-weight:600;margin-bottom:6px;}
.revsubt{color:var(--muted);font-size:13px;letter-spacing:1px;margin-bottom:22px;}
.slider{position:relative;max-width:360px;margin:0 auto;}
.slider .track .sl{display:none;}
.slider .track .sl.active{display:block;}
.slider .track iframe{width:100%;height:560px;border:1px solid var(--line);border-radius:10px;background:#000;display:block;}
.slider .track img{width:100%;height:auto;border:1px solid var(--line);border-radius:10px;background:#ffffff10;display:block;}
.sarrow{position:absolute;top:50%;transform:translateY(-50%);width:38px;height:38px;border-radius:50%;background:rgba(201,162,75,.92);color:#0b0a09;font-size:19px;border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:2;}
.sarrow.prev{left:-8px;}.sarrow.next{right:-8px;}
@media(max-width:480px){.sarrow.prev{left:2px;}.sarrow.next{right:2px;}}
.sdots{display:flex;gap:6px;justify-content:center;margin-top:16px;flex-wrap:wrap;}
.sdots .dot{width:7px;height:7px;border-radius:50%;background:var(--muted2);cursor:pointer;}
.sdots .dot.on{background:var(--gold);}
.vid{max-width:780px;margin:54px auto 0;aspect-ratio:16/9;}
.vid iframe{width:100%;height:100%;border:1px solid var(--line);border-radius:10px;background:#000;}
.vidlbl{text-align:center;margin-top:90px;}
.vidlbl .revhead{font-size:24px;}

.mats{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin-top:34px;background:var(--line);border:1px solid var(--line);}
@media(max-width:760px){.mats{grid-template-columns:1fr;}}
.mat{background:var(--bg);}
.mat .thumb{aspect-ratio:16/10;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;overflow:hidden;}
.mat .thumb img{width:100%;height:100%;object-fit:cover;}
.mat .body{padding:34px 36px;}
.mat h4{font-family:var(--serif);font-size:21px;font-weight:600;}
.mat p{color:var(--muted);font-size:14px;margin:10px 0 22px;font-weight:300;}
.lnk{font-size:12px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;border-bottom:1px solid var(--goldsoft);padding-bottom:4px;}
.matlbl{margin-top:90px;text-align:center;}

.cta{text-align:center;border-top:1px solid var(--line);}

footer{border-top:1px solid var(--line);padding:56px 0;color:var(--muted2);font-size:12px;letter-spacing:1px;}
footer .top{display:flex;justify-content:space-between;flex-wrap:wrap;gap:18px;align-items:center;}
footer a{color:var(--gold);}

.navtoggle{display:none;background:none;border:none;color:var(--gold);font-size:22px;cursor:pointer;line-height:1;}
@media(max-width:980px){.navtoggle{display:block;}}
.mobilemenu{display:none;position:fixed;top:80px;left:0;right:0;z-index:59;background:rgba(11,10,9,.98);border-bottom:1px solid var(--line);padding:10px 40px 22px;flex-direction:column;}
.mobilemenu.open{display:flex;}
.mobilemenu a{padding:15px 0;font-size:14px;letter-spacing:2px;color:var(--muted);border-bottom:1px solid var(--line);}
.mobilemenu a.cta{color:var(--gold);border-bottom:none;}

.stickycta{display:none;}
@media(max-width:760px){
  .stickycta{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;padding:10px 14px calc(10px + env(safe-area-inset-bottom));background:rgba(11,10,9,.96);border-top:1px solid var(--line);backdrop-filter:blur(6px);}
  .stickycta a{flex:1;text-align:center;padding:15px 0;border-radius:4px;font-size:14px;letter-spacing:1px;font-weight:500;}
  .stickycta a.p{background:var(--gold);color:#0b0a09;}
  .stickycta a.s{border:1px solid var(--gold);color:var(--gold);}
  body{padding-bottom:74px;}
}

.classinfo{display:grid;grid-template-columns:repeat(3,1fr);margin-top:60px;border-top:1px solid var(--line);border-left:1px solid var(--line);text-align:left;}
@media(max-width:680px){.classinfo{grid-template-columns:1fr;}}
.cinfo{padding:36px 30px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);}
.cinfo .cl{font-size:11px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;}
.cinfo .cv{font-size:18px;margin-top:12px;}
.cinfo .cv small{color:var(--muted);font-size:13px;display:block;margin-top:5px;font-weight:300;}

.faq{max-width:780px;margin:54px auto 0;text-align:left;}
.faq details{border-top:1px solid var(--line);}
.faq details:last-child{border-bottom:1px solid var(--line);}
.faq summary{list-style:none;cursor:pointer;padding:22px 4px;font-size:17px;display:flex;justify-content:space-between;align-items:center;gap:16px;}
.faq summary::-webkit-details-marker{display:none;}
.faq summary::after{content:"+";color:var(--gold);font-size:22px;line-height:1;}
.faq details[open] summary::after{content:"\\2212";}
.faq .fa{padding:0 4px 24px;color:var(--muted);font-size:15px;line-height:1.8;}

.modal{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;background:rgba(5,5,4,.9);backdrop-filter:blur(4px);padding:28px;}
.modal.open{display:flex;}
.mbox{max-width:900px;width:100%;max-height:90vh;display:flex;flex-direction:column;background:var(--bg2);border:1px solid var(--line);border-radius:6px;overflow:hidden;}
.mhead{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;border-bottom:1px solid var(--line);}
.mhead .mt{font-family:var(--serif);font-size:16px;letter-spacing:1px;color:var(--gold);}
.mclose{font-size:20px;color:var(--muted);cursor:pointer;line-height:1;padding:4px 8px;border:1px solid var(--line);border-radius:3px;}
.mclose:hover{color:var(--ink);}
.mbody{padding:22px;overflow:auto;}
.stage{position:relative;display:flex;align-items:center;justify-content:center;background:#0c0b09;border-radius:4px;min-height:300px;}
.slide{display:none;max-width:100%;max-height:66vh;object-fit:contain;border-radius:4px;}
.slide.active{display:block;}
.arrow{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;background:rgba(201,162,75,.9);color:#0b0a09;font-size:20px;display:flex;align-items:center;justify-content:center;cursor:pointer;border:none;}
.arrow.prev{left:12px;}.arrow.next{right:12px;}
.mcap{text-align:center;color:var(--muted);font-size:13px;letter-spacing:1px;margin-top:16px;min-height:18px;}
.dots{display:flex;gap:7px;justify-content:center;margin-top:16px;flex-wrap:wrap;}
.dot{width:8px;height:8px;border-radius:50%;background:var(--muted2);cursor:pointer;}
.dot.on{background:var(--gold);}
.curvid{aspect-ratio:16/9;width:100%;margin-bottom:18px;}
.curvid iframe{width:100%;height:100%;border:0;border-radius:4px;}
.curimg{width:100%;border-radius:4px;display:block;}
.curcap{text-align:center;color:var(--muted);font-size:12px;letter-spacing:3px;text-transform:uppercase;margin:18px 0 8px;}

.pgrid{display:grid;grid-template-columns:1fr 1.05fr;gap:64px;align-items:center;margin-top:80px;text-align:left;}
.pgrid .report{margin:0;max-width:none;}
.plist .sysrow .t{font-size:18px;}
.plist .sysrow .t small{display:block;color:var(--muted);font-size:13.5px;margin-top:4px;font-weight:300;letter-spacing:0;}
@media(max-width:900px){.pgrid{grid-template-columns:1fr;gap:48px;}}

.zzwrap{margin-top:20px;text-align:left;}
