export default function LandingPage() {
  useEffect(() => {
    const w = window as any

    w.toggleMenu = () => {
      document.getElementById("mobilemenu")?.classList.toggle("open")
    }

    let sIdx = 0
    const slides = () => Array.from(document.querySelectorAll("#sysModal .slide")) as HTMLElement[]
    const showS = (n: number) => {
      const s = slides()
      const total = s.length
      if (!total) return
      sIdx = (n + total) % total
      s.forEach((el, i) => el.classList.toggle("active", i === sIdx))
      const cap = document.getElementById("sysCap")
      if (cap) cap.textContent = s[sIdx].dataset.cap || ""
      document.querySelectorAll("#sysDots .dot").forEach((d, i) => d.classList.toggle("on", i === sIdx))
    }

    w.openM = (id: string) => {
      const m = document.getElementById(id)
      if (!m) return
      m.classList.add("open")
      document.body.style.overflow = "hidden"
      if (id === "sysModal") showS(0)
    }
    w.closeM = (id: string) => {
      const m = document.getElementById(id)
      if (!m) return
      m.classList.remove("open")
      document.body.style.overflow = ""
    }
    w.sysNext = (d: number) => showS(sIdx + d)

    const sysDots = document.getElementById("sysDots")
    if (sysDots && !sysDots.childElementCount) {
      slides().forEach((_, i) => {
        const b = document.createElement("span")
        b.className = "dot" + (i === 0 ? " on" : "")
        b.onclick = () => showS(i)
        sysDots.appendChild(b)
      })
    }

    document.querySelectorAll(".modal").forEach((m) => {
      m.addEventListener("click", (e) => {
        if (e.target === m) w.closeM((m as HTMLElement).id)
      })
    })

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { w.closeM("sysModal"); w.closeM("curModal") }
      const sm = document.getElementById("sysModal")
      if (sm?.classList.contains("open")) {
        if (e.key === "ArrowRight") w.sysNext(1)
        if (e.key === "ArrowLeft") w.sysNext(-1)
      }
    }
    document.addEventListener("keydown", onKey)

    document.querySelectorAll(".slider").forEach((sl) => {
      const items = Array.from(sl.querySelectorAll(".track > .sl")) as HTMLElement[]
      const dotsC = sl.querySelector(".sdots")
      let idx = 0
      const show = (n: number) => {
        if (!items.length) return
        idx = (n + items.length) % items.length
        items.forEach((el, i) => el.classList.toggle("active", i === idx))
        if (dotsC) dotsC.querySelectorAll(".dot").forEach((d, i) => d.classList.toggle("on", i === idx))
      }
      const pv = sl.querySelector(".sarrow.prev") as HTMLElement | null
      const nx = sl.querySelector(".sarrow.next") as HTMLElement | null
      if (pv) pv.onclick = () => show(idx - 1)
      if (nx) nx.onclick = () => show(idx + 1)
      let tx = 0
      sl.addEventListener("touchstart", (e) => { tx = (e as TouchEvent).touches[0].clientX }, { passive: true })
      sl.addEventListener("touchend", (e) => {
        const dx = (e as TouchEvent).changedTouches[0].clientX - tx
        if (Math.abs(dx) > 40) show(dx < 0 ? idx + 1 : idx - 1)
      }, { passive: true })
      if (dotsC && !dotsC.childElementCount) {
        items.forEach((_, i) => {
          const b = document.createElement("span")
          b.className = "dot" + (i === 0 ? " on" : "")
          b.onclick = () => show(i)
          dotsC.appendChild(b)
        })
      }
      show(0)
    })

    return () => {
      document.removeEventListener("keydown", onKey)
    }
  }, [])

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div dangerouslySetInnerHTML={{ __html: BODY }} />
    </>
  )
}
